CREATE TABLE shelter (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, lat DOUBLE PRECISION NOT NULL, lon DOUBLE PRECISION NOT NULL, underserved BOOLEAN NOT NULL);
CREATE TABLE resource_stock (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, shelter_id BIGINT NOT NULL REFERENCES shelter(id), category VARCHAR(40) NOT NULL, available INTEGER NOT NULL CHECK(available>=0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0), version BIGINT NOT NULL DEFAULT 0, UNIQUE(shelter_id,category));
CREATE TABLE citizen_request (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, shelter_id BIGINT NOT NULL REFERENCES shelter(id), category VARCHAR(40) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), fulfilled INTEGER NOT NULL DEFAULT 0, urgency INTEGER NOT NULL CHECK(urgency BETWEEN 1 AND 5), source_key VARCHAR(100) UNIQUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE volunteer (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, display_name VARCHAR(100) NOT NULL, shelter_id BIGINT NOT NULL REFERENCES shelter(id), capacity INTEGER NOT NULL CHECK(capacity>=0), committed INTEGER NOT NULL DEFAULT 0 CHECK(committed>=0), active BOOLEAN NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE allocation_plan (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE assignment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, plan_id BIGINT NOT NULL REFERENCES allocation_plan(id), request_id BIGINT NOT NULL REFERENCES citizen_request(id), stock_id BIGINT NOT NULL REFERENCES resource_stock(id), volunteer_id BIGINT NOT NULL REFERENCES volunteer(id), quantity INTEGER NOT NULL CHECK(quantity>0), distance_km DOUBLE PRECISION NOT NULL, explanation VARCHAR(1000) NOT NULL, status VARCHAR(32) NOT NULL, UNIQUE(plan_id,request_id,stock_id,volunteer_id));
CREATE TABLE sync_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sync_key VARCHAR(100) NOT NULL UNIQUE, payload_hash VARCHAR(64) NOT NULL, request_id BIGINT NOT NULL REFERENCES citizen_request(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE audit_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, action VARCHAR(60) NOT NULL, details VARCHAR(1500) NOT NULL, at_time TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_request_category ON citizen_request(category);
CREATE INDEX ix_assignment_plan ON assignment(plan_id);
